declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Enable : BOOL;
    Tick : BOOL;
END_VAR
VAR_OUTPUT
    Red : BOOL;
    Green : BOOL;
    Amber : BOOL;
    Phase : USINT;
END_VAR
VAR
CurrentPhase : USINT := 0;
    Elapsed : USINT := 0;
    Limit : USINT := 2;
END_VAR

implementation:
IF NOT Enable THEN
    CurrentPhase := 0; Elapsed := 0;
ELSIF Tick THEN
    CASE CurrentPhase OF 0: Limit := 2; 1: Limit := 3; 2: Limit := 1; END_CASE;
    Elapsed := Elapsed + 1;
    IF Elapsed >= Limit THEN
        Elapsed := 0;
        IF CurrentPhase = 2 THEN CurrentPhase := 0; ELSE CurrentPhase := CurrentPhase + 1; END_IF;
    END_IF;
END_IF;
Phase := CurrentPhase;
Red := CurrentPhase = 0;
Green := CurrentPhase = 1;
Amber := CurrentPhase = 2;
